import { decide } from "./decide";
import { commit } from "../store/commit";

export async function dispatch(command: unknown) {
  const events = decide(command);
  await commit(events);
  return events;
}

files.src/orchestration/decide.ts:
export function decide(command: unknown) {
  return [{ type: "accepted", command }];
}

